// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 warpTs, address caller) public {
        warpTs = bound(warpTs, 1, type(uint64).max - 1);
        vm.assume(caller != address(0));

        vm.warp(warpTs);
        vm.roll(block.number + 1);

        uint256 amount = 10 ether;
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("");

        if (ok) {
            uint256 recorded = c.pastBlockTime();
            assertTrue(recorded == block.timestamp);
        } else {
            assertTrue(false);
        }
    }
}
